import random
import string
from typing import List

# Target data type: arbitrary string
# Strategy: produce a bytes buffer containing many NUL-terminated strings that
# exercise various code paths in the stubs. Keep total size <= 4096 bytes.

SAFE_NAME_CHARS = string.ascii_letters + string.digits + "_-"

def _rand_ascii(r: random.Random, min_len: int, max_len: int) -> str:
    n = r.randint(min_len, max_len)
    alphabet = string.ascii_letters + string.digits + string.punctuation + " "
    s = ''.join(r.choice(alphabet) for _ in range(n))
    return s.replace('\x00', ' ')

def _rand_token(r: random.Random, min_len: int, max_len: int) -> str:
    n = r.randint(min_len, max_len)
    return ''.join(r.choice(SAFE_NAME_CHARS) for _ in range(n))

def _encoder_name(r: random.Random) -> str:
    common = ["StandardEncoding", "WinAnsiEncoding", "MacRomanEncoding"]
    if r.random() < 0.7:
        return r.choice(common)
    return _rand_token(r, 3, 24)

def _font_name(r: random.Random) -> str:
    common = [
        "Helvetica", "Times-Roman", "Courier", "Helvetica-Bold",
        "Times-BoldItalic", "Courier-Oblique"
    ]
    if r.random() < 0.7:
        return r.choice(common)
    return _rand_token(r, 3, 32)

def _icc_name(r: random.Random) -> str:
    base = r.choice(["sRGB IEC61966-2.1", "USWebCoatedSWOP.icc", "AdobeRGB1998", "DisplayP3", "FOGRA39"])
    if r.random() < 0.4:
        base += "-v" + str(r.randint(1, 5))
    return base

def _mime_subtype(r: random.Random) -> str:
    choices = ["pdf", "zip", "octet-stream", "png", "jpeg", "plain", "xml", "u3d"]
    return r.choice(choices)

def _glyph_name(r: random.Random) -> str:
    return r.choice(["A", "B", "space", "period", "comma", "uni0041", "uni03A9", "hyphen"])

def _tag_name6(r: random.Random) -> str:
    n = r.randint(1, 6)
    alphabet = string.ascii_letters + string.digits + "_"
    return ''.join(r.choice(alphabet) for _ in range(n))

def _password(r: random.Random) -> str:
    opts = [
        "", "owner", "user", _rand_ascii(r, 1, 64), _rand_ascii(r, 10, 40),
        "pässWörd123!",
    ]
    return r.choice(opts)

def _xml_fragment(r: random.Random) -> str:
    title = _rand_ascii(r, 5, 15).replace('<', '').replace('>', '')
    creator = _rand_ascii(r, 3, 10).replace('<', '').replace('>', '')
    return f"<x:xmpmeta><rdf:RDF><rdf:Description><dc:title>{title}</dc:title><xmp:CreatorTool>{creator}</xmp:CreatorTool></rdf:Description></rdf:RDF></x:xmpmeta>"

def _filename(r: random.Random) -> str:
    parts = [
        _rand_token(r, 3, 8),
        _rand_token(r, 3, 8) + r.choice([".pdf", ".txt", ".bin", ".dat", ".icc"]) 
    ]
    if r.random() < 0.4:
        parts.insert(0, _rand_token(r, 3, 6))
    sep = "/" if r.random() < 0.5 else "\\"  # POSIX or Windows-style
    return sep.join(parts)

def _number_strs(r: random.Random) -> List[str]:
    return [
        str(r.randint(-10**9, 10**9)),
        f"{r.uniform(-1e6,1e6):.6f}",
        "0", "-0", "+12345", "-98765", "3.14159", "2.9979e8"
    ]

def _annotation_text(r: random.Random) -> str:
    base = _rand_ascii(r, 5, 80)
    if r.random() < 0.5:
        base += "\n" + _rand_ascii(r, 5, 40)
    return base

def _pdf_name_like(r: random.Random) -> str:
    return _rand_token(r, 1, 32)

def _limit_size(chunks: List[bytes], limit: int = 4096) -> List[bytes]:
    out = []
    total = 0
    for c in chunks:
        if total + len(c) > limit:
            break
        out.append(c)
        total += len(c)
    return out

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    chunks: List[bytes] = []

    # 1) Encoder and Font names
    chunks += [
        _encoder_name(r).encode('utf-8') + b"\x00",
        _font_name(r).encode('utf-8') + b"\x00",
    ]

    # 2) ICC profile name and XMP extension description
    chunks += [
        _icc_name(r).encode('utf-8') + b"\x00",
        _xml_fragment(r).encode('utf-8') + b"\x00",
    ]

    # 3) Info attributes
    for _ in range(5):
        chunks.append(_rand_ascii(r, 5, 40).encode('utf-8') + b"\x00")

    # 4) Page label prefix
    chunks.append(_pdf_name_like(r).encode('utf-8') + b"\x00")

    # 5) Annotation texts
    for _ in range(8):
        chunks.append(_annotation_text(r).encode('utf-8') + b"\x00")

    # 6) Stamp names optional text
    chunks.append(_rand_ascii(r, 0, 32).encode('utf-8') + b"\x00")

    # 7) Projection/line annot extra strings
    chunks.append(_rand_ascii(r, 0, 64).encode('utf-8') + b"\x00")

    # 8) 3D measure: units, names, text
    chunks.append(_rand_token(r, 1, 8).encode('utf-8') + b"\x00")  # units
    chunks.append(_rand_ascii(r, 3, 24).encode('utf-8') + b"\x00")  # measure name
    chunks.append(_annotation_text(r).encode('utf-8') + b"\x00")     # measure text

    # 9) Passwords: owner/user combos and EncryptDict
    for _ in range(4):
        chunks.append(_password(r).encode('utf-8') + b"\x00")

    # 10) Raw image-like blob (as string-backed bytes) followed by NUL
    blob_len = r.randint(256, 2048)
    blob = bytes(r.getrandbits(8) for _ in range(blob_len))
    chunks.append(blob + b"\x00")

    # 11) Glyph names and tag name (Type1 width by name; TTF tag)
    chunks.append(_glyph_name(r).encode('utf-8') + b"\x00")
    chunks.append(_tag_name6(r).encode('utf-8') + b"\x00")

    # 12) MIME subtype (EmbeddedFile)
    chunks.append(_mime_subtype(r).encode('utf-8') + b"\x00")

    # 13) Filenames for fopen
    for _ in range(3):
        chunks.append(_filename(r).encode('utf-8') + b"\x00")

    # 14) Numeric-looking strings for AToI/AToF
    for s in _number_strs(r):
        chunks.append(s.encode('utf-8') + b"\x00")

    # 15) PDF name-like tokens for arrays/dicts/name writes
    for _ in range(6):
        chunks.append(_pdf_name_like(r).encode('utf-8') + b"\x00")

    # 16) General-purpose random strings
    for _ in range(12):
        chunks.append(_rand_ascii(r, 1, 128).encode('utf-8') + b"\x00")

    chunks = _limit_size(chunks, 4096)

    return b"".join(chunks)

import random
from typing import Tuple

# Target data type: raw 1-bit image data (packed bits), but the fuzzers also use it
# as generic blobs for HPDF_LoadRawImageFromMem (8bpc Gray/RGB/CMYK). We should
# generate bytes that can validly serve both purposes. We will build a buffer that
# contains multiple concatenated image planes so that a prefix of the buffer can
# satisfy size computations the stubs perform after they randomly pick dimensions
# and color spaces. The generator focuses on producing visually diverse, valid
# raster data patterns with small dimensions to keep sizes <= 4096.

MAX_SIZE = 4096


def _pattern_solid(width: int, height: int, channels: int, values: Tuple[int, ...]) -> bytes:
    row = bytes([values[c % len(values)] for c in range(channels)] * width)
    return row * height


def _pattern_checker(width: int, height: int, channels: int) -> bytes:
    # 8bpc checkerboard per pixel; alternates 0/255 across x,y. For CMYK, use 4-tuple.
    plane0_on = 255
    plane0_off = 0
    pix = bytearray()
    for y in range(height):
        for x in range(width):
            v = plane0_on if ((x ^ y) & 1) else plane0_off
            if channels == 1:
                pix.append(v)
            elif channels == 3:
                # RGB: vary channels to create more variety
                pix.extend((v, 255 - v, (x * 17 + y * 31) & 0xFF))
            else:
                # CMYK simple mapping
                c = v
                m = (x * 11 + y * 13) & 0xFF
                yv = (x * 7 + y * 5) & 0xFF
                k = 255 - v
                pix.extend((c, m, yv, k))
    return bytes(pix)


def _pattern_gradient(width: int, height: int, channels: int) -> bytes:
    pix = bytearray()
    for y in range(height):
        for x in range(width):
            base = int(255 * x / max(1, width - 1))
            alt = int(255 * y / max(1, height - 1))
            if channels == 1:
                pix.append(base)
            elif channels == 3:
                pix.extend((base, alt, (base + alt) // 2))
            else:
                # CMYK gradient: use complementary K
                k = 255 - ((base + alt) // 2)
                pix.extend((base, alt, (base * 3 // 4), k))
    return bytes(pix)


def _pack_1bpp_rowbits(bits: list) -> bytes:
    # Pack a list of 0/1 bits into bytes MSB-first, as libharu expects typical raw 1bpp
    out = bytearray()
    acc = 0
    nbits = 0
    for b in bits:
        acc = (acc << 1) | (1 if b else 0)
        nbits += 1
        if nbits == 8:
            out.append(acc & 0xFF)
            acc = 0
            nbits = 0
    if nbits:
        acc <<= (8 - nbits)
        out.append(acc & 0xFF)
    return bytes(out)


def _pattern_1bpp(width: int, height: int, black_is1: bool, top_is_first: bool) -> bytes:
    # Build a simple 1bpp pattern combining stripes and a diagonal
    rows = []
    for y in range(height):
        bits = []
        for x in range(width):
            on = ((x // 2) % 2) ^ ((y // 2) % 2)  # coarse checker stripes
            if x == y or x + y == width - 1:
                on = 1  # draw diagonals
            bits.append(on)
        rows.append(_pack_1bpp_rowbits(bits))
    if not top_is_first:
        rows.reverse()
    buf = b"".join(rows)
    if not black_is1:
        # invert bits
        buf = bytes([b ^ 0xFF for b in buf])
    return buf


def _make_valid_blobs(rng: random.Random) -> bytes:
    chunks = []

    # 1) Include several 1bpp images with varying dimensions and flags.
    for _ in range(rng.randint(1, 3)):
        w = rng.randint(1, 64)
        h = rng.randint(1, 64)
        black_is1 = bool(rng.getrandbits(1))
        top_is_first = bool(rng.getrandbits(1))
        chunks.append(_pattern_1bpp(w, h, black_is1, top_is_first))
        if sum(len(c) for c in chunks) > MAX_SIZE:
            break

    # 2) Include 8bpc raw images for GRAY/RGB/CMYK with small sizes and diverse patterns.
    for cs_channels in (1, 3, 4):
        w = rng.randint(1, 48 if cs_channels == 4 else 64)
        h = rng.randint(1, 48 if cs_channels == 4 else 64)
        kind = rng.choice(["solid", "checker", "gradient"])
        if kind == "solid":
            if cs_channels == 1:
                val = rng.choice([0, 64, 128, 192, 255])
                blob = _pattern_solid(w, h, 1, (val,))
            elif cs_channels == 3:
                vals = tuple(rng.choice([0, 64, 128, 192, 255]) for _ in range(3))
                blob = _pattern_solid(w, h, 3, vals)
            else:
                vals = tuple(rng.choice([0, 85, 170, 255]) for _ in range(4))
                blob = _pattern_solid(w, h, 4, vals)
        elif kind == "checker":
            blob = _pattern_checker(w, h, cs_channels)
        else:
            blob = _pattern_gradient(w, h, cs_channels)
        chunks.append(blob)
        if sum(len(c) for c in chunks) > MAX_SIZE:
            break

    # 3) Add a few small random noise tiles to increase entropy while staying valid for size checks.
    for _ in range(rng.randint(1, 3)):
        w = rng.randint(1, 32)
        h = rng.randint(1, 32)
        ch = rng.choice([1, 3, 4])
        size = w * h * ch
        noise = bytes(rng.getrandbits(8) for _ in range(size))
        chunks.append(noise)
        if sum(len(c) for c in chunks) > MAX_SIZE:
            break

    # Truncate to max size
    buf = b"".join(chunks)
    return buf[:MAX_SIZE]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    return _make_valid_blobs(rng)
